fast_pseudocode:
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 128, 'YBLOCK': 2}, num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 256, 'YBLOCK': 2}, num_warps=4, num_stages=3),
        triton.Config({'XBLOCK': 512, 'YBLOCK': 2}, num_warps=8, num_stages=3),
        # ... more configs spanning XBLOCK in {128,256,512},
        #     YBLOCK in {2,4,8,16,32}, num_stages in {2,3,4}
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(..., YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    # same body, tile sizes now come from autotuner
    ...

def launch():
    grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
    kernel[grid](...)  # no explicit XBLOCK/YBLOCK kwargs
